import{_ as l,o as n,c as i,a5 as t}from"./chunks/framework.CXroN2RO.js";const u=JSON.parse('{"title":"第15章 ゲームエンジンアーキテクチャとECS ── エンジンの解剖学","description":"","frontmatter":{"title":"第15章 ゲームエンジンアーキテクチャとECS ── エンジンの解剖学","study":{"source":"IT教本","kind":"学習ガイド","status":"学習計画・概要","summary":"ここまでの全章は部品だった。この章で部品を「エンジン」に組み上げる。 エンジンの層構造・ゲームオブジェクトモデル・アセットパイプライン・ シーン管理を一般論として理解しておくと、次章以降のUnity/UEが"}},"headers":[],"relativePath":"guide/low-level/engine-architecture-ecs.md","filePath":"guide/low-level/engine-architecture-ecs.md"}'),e={name:"guide/low-level/engine-architecture-ecs.md"};function s(o,a,r,d,p,c){return n(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="第15章-ゲームエンジンアーキテクチャとecs-──-エンジンの解剖学" tabindex="-1">第15章 ゲームエンジンアーキテクチャとECS ── エンジンの解剖学 <a class="header-anchor" href="#第15章-ゲームエンジンアーキテクチャとecs-──-エンジンの解剖学" aria-label="Permalink to &quot;第15章 ゲームエンジンアーキテクチャとECS ── エンジンの解剖学&quot;">​</a></h1><h2 id="学ぶ理由" tabindex="-1">学ぶ理由 <a class="header-anchor" href="#学ぶ理由" aria-label="Permalink to &quot;学ぶ理由&quot;">​</a></h2><p>ここまでの全章は部品だった。この章で部品を「エンジン」に組み上げる。 エンジンの層構造・ゲームオブジェクトモデル・アセットパイプライン・ シーン管理を一般論として理解しておくと、次章以降のUnity/UEが 「同じ問題への2つの解答例」として読めるようになる。そしてECSは、 第3章(キャッシュ)・第9章(仮想関数のコスト)の知識が結晶した 現代の設計様式である。</p><h2 id="到達目標" tabindex="-1">到達目標 <a class="header-anchor" href="#到達目標" aria-label="Permalink to &quot;到達目標&quot;">​</a></h2><ul><li>エンジンのレイヤ構造(プラットフォーム→コア→リソース→シーン→ゲーム)を描ける</li><li>ゲームオブジェクトモデル3類型(継承/コンポーネント/ECS)の得失を説明できる</li><li>アーキタイプ型とスパースセット型ECSの内部実装を説明できる</li><li>アセットパイプライン(インポート→クック→ロード)の役割を説明できる</li><li>数千行規模の「ミニエンジン」を自力で設計・実装できる</li></ul><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to &quot;前提知識&quot;">​</a></h2><p>第3,6,9,10章(キャッシュ・アロケータ・C++・データ構造)、 第12〜14章(レンダリング・API・ループ)。</p><h2 id="学ぶ内容" tabindex="-1">学ぶ内容 <a class="header-anchor" href="#学ぶ内容" aria-label="Permalink to &quot;学ぶ内容&quot;">​</a></h2><ol><li><strong>エンジンのレイヤ構造(Gregory本の地図)</strong><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ゲーム固有コード(タイトル側)</span></span>
<span class="line"><span>─────────────────────────────</span></span>
<span class="line"><span>ゲームプレイ基盤(オブジェクトモデル・イベント・スクリプト)</span></span>
<span class="line"><span>シーン/ワールド(シーングラフ・空間分割・ストリーミング)</span></span>
<span class="line"><span>機能システム(レンダラ/物理/アニメ/オーディオ/UI/AI)</span></span>
<span class="line"><span>リソース管理(アセットロード・参照解決・キャッシュ)</span></span>
<span class="line"><span>コア(数学・コンテナ・アロケータ・ジョブ・ログ・シリアライズ)</span></span>
<span class="line"><span>プラットフォーム抽象(ウィンドウ・入力・ファイル・スレッド・RHI)</span></span>
<span class="line"><span>─────────────────────────────</span></span>
<span class="line"><span>OS / ドライバ / ハードウェア(第2〜13章)</span></span></code></pre></div><ul><li>依存は必ず下向き。上位層は下位層を知るが逆は禁止</li></ul></li><li><strong>ゲームオブジェクトモデル(エンジン設計の中心問題)</strong><ul><li>(a) 継承ベース: <code>Enemy : Character : Actor</code>(初期UEの姿) → ひし形・神クラス・柔軟性欠如で破綻しがち</li><li>(b) コンポーネント指向: GameObjectにComponentを刺す(Unity/現UE) → 合成による柔軟性。だがポインタだらけでキャッシュに不利</li><li>(c) <strong>ECS</strong>: Entity=ただのID、Component=純データ、System=処理 → データ指向の帰結。UnityのDOTS、Overwatch等</li></ul></li><li><strong>ECSの内部実装(2大流派)</strong><ul><li><strong>アーキタイプ型</strong>(Unity DOTS, flecs): 同じコンポーネント構成の エンティティを同じ「テーブル」に連続配置。イテレーションが爆速、 構成変更(add/remove)が高い</li><li><strong>スパースセット型</strong>(EnTT): コンポーネント毎に密配列+疎な索引。 add/removeが速い、複数コンポーネント横断はやや劣る</li><li>generation付きEntityID(第10章ハンドルの回収)</li><li>どちらも本質は「第3章のキャッシュ理論の応用」であること</li></ul></li><li><strong>リソース/アセットパイプライン</strong><ul><li>ソースアセット(FBX/PNG)→インポート→中間形式→<strong>クック</strong> (プラットフォーム別最適形式)→パッケージ→実行時ロード</li><li>参照の表現(GUID/パス)、依存グラフ、ホットリロード</li><li>実行時: 非同期ロード(第8章I/O回収)、参照カウント、 ストリーミング(距離ベース、UEのWorld Partitionの原理)</li></ul></li><li><strong>フレームの全体オーケストレーション</strong><ul><li>システム更新順序、フェーズ(入力→ゲーム→物理→アニメ→ カメラ→カリング→描画コマンド→提出)</li><li>ジョブグラフ化(第8章ジョブシステムの回収)、 メインスレッド/レンダースレッド分離(UEの構造の先取り)</li><li>イベント/メッセージング(即時 vs キュー、フレーム跨ぎ)</li></ul></li><li><strong>周辺システムの概観(深入りは各専門書)</strong><ul><li>物理(broadphase=第10章空間分割、narrowphase、ソルバ)</li><li>アニメ(スケルトン、ブレンド、ステートマシン)</li><li>オーディオ(ミキサ、レイテンシ ← リングバッファの実用)</li><li>UI(イミディエイト vs リテイン、Dear ImGuiの思想)</li><li>シリアライズ(セーブ・シーンファイル・リフレクションの必要性 ← UEへ伏線)</li></ul></li><li><strong>ミニエンジンを作る(本教本最大の演習)</strong></li></ol><h2 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h2><ul><li><strong>レイヤと依存方向</strong> ── 大規模ソフトの背骨</li><li><strong>合成 &gt; 継承</strong> ── ゲームオブジェクト設計の歴史的教訓</li><li><strong>ECS = ID + 連続データ + 一括処理</strong>(キャッシュ理論の結晶)</li><li><strong>アセットは「ビルドされる」</strong>(クックという概念)</li><li><strong>エンジンとは「毎フレームの決まった仕事の工場」</strong></li></ul><h2 id="ゲーム開発との関係" tabindex="-1">ゲーム開発との関係 <a class="header-anchor" href="#ゲーム開発との関係" aria-label="Permalink to &quot;ゲーム開発との関係&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現場の事象</th><th>この章の知識</th></tr></thead><tbody><tr><td>UnityのGameObject/Component</td><td>モデル(b)の実装</td></tr><tr><td>UEのActor/ActorComponent</td><td>(a)+(b)のハイブリッド</td></tr><tr><td>Unity DOTS / Mass Entity(UE)</td><td>ECS</td></tr><tr><td>アセットのインポート待ち・クック</td><td>アセットパイプライン</td></tr><tr><td>「Updateの順序が保証されない」問題</td><td>システム更新順序設計</td></tr><tr><td>オープンワールドのストリーミング</td><td>リソース管理・World Partition</td></tr></tbody></table><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p><strong>ミニエンジン制作(2Dで十分。3Dは意欲があれば)</strong></p><ol><li>設計: レイヤ図とモジュール一覧を先に紙に描け(コア/プラットフォーム/ レンダラ/リソース/シーン/ゲーム)。</li><li>コア層: 数学(第10章の自作品)、フレームアロケータ(第6章の自作品)、 ログ、アサートを整備せよ。</li><li><strong>スパースセット型ECSを自作せよ</strong>(entity生成破棄、component add/remove/get、view(複数component横断イテレーション)。500行程度)。</li><li>システム: MovementSystem、CollisionSystem(グリッド)、 RenderSystem(スプライトバッチング)を実装せよ。</li><li>リソース: テクスチャ/サウンドのキャッシュ付きローダ(参照カウント)を 実装せよ。</li><li>これらで<strong>小ゲームを1本完成させよ</strong>(シューティングや Vampire Survivors風など、物量が出るものがECSの真価を示す)。</li><li>敵1万体を出し、(第18章の道具で)プロファイルして ボトルネックを1つ潰せ。</li><li>自作ECSとEnTTで同じ処理を書き、速度と設計を比較せよ。</li></ol><h2 id="おすすめ書籍" tabindex="-1">おすすめ書籍 <a class="header-anchor" href="#おすすめ書籍" aria-label="Permalink to &quot;おすすめ書籍&quot;">​</a></h2><ul><li><strong>『ゲームエンジン・アーキテクチャ 第3版』Jason Gregory</strong> ── この章の主教材にして業界標準(ノーティドッグ)。通読推奨</li><li>『ゲームプログラミングパターン』── コンポーネント/更新メソッド/ オブジェクトプール等、Web無料</li><li>『Game Programming in C++』Sanjay Madhav ── ミニエンジン制作の伴走書</li><li>Bob Nystrom &amp; Catlike Coding(Web)── 実装記事群</li></ul><h2 id="おすすめoss" tabindex="-1">おすすめOSS <a class="header-anchor" href="#おすすめoss" aria-label="Permalink to &quot;おすすめOSS&quot;">​</a></h2><ul><li><strong>EnTT</strong>(skypjack/entt)── スパースセットECSの決定版。wiki が教科書級</li><li><strong>flecs</strong>(SanderMertens/flecs)── アーキタイプ型。作者のECS FAQ/ ブログ「Building an ECS」は必読</li><li><strong>Godot</strong> ── フル機能OSSエンジン。「エンジン全体の実物」として散策 (servers/ 以下にレンダラ・物理の分離構造が見える)</li><li><strong>Bevy</strong>(Rust)── モダンECSエンジンの設計参考(発展)</li><li>Dear ImGui ── ツールUIの業界標準。自作エンジンに即組み込め</li></ul><h2 id="おすすめ動画" tabindex="-1">おすすめ動画 <a class="header-anchor" href="#おすすめ動画" aria-label="Permalink to &quot;おすすめ動画&quot;">​</a></h2><ul><li>GDC &quot;Overwatch Gameplay Architecture and Netcode&quot;(ECS実戦の金字塔)</li><li>Unity &quot;DOTS&quot; 公式解説シリーズ</li><li>The Cherno &quot;Game Engine&quot; シリーズ(Hazelエンジン制作)</li><li>Bobby Anguelov のゲームオブジェクトモデル講演 (&quot;An Introduction to Gameplay Architecture&quot;)</li></ul><h2 id="読むべきソースコード" tabindex="-1">読むべきソースコード <a class="header-anchor" href="#読むべきソースコード" aria-label="Permalink to &quot;読むべきソースコード&quot;">​</a></h2><ul><li>EnTT <code>entt/entity/registry.hpp</code>(スパースセットの本丸)</li><li>flecsのアーキタイプ管理部+作者ブログ対照読み</li><li>Godot <code>main/main.cpp</code> の <code>Main::iteration()</code>(エンジンのループ実物)</li><li>自作ミニエンジン(最重要。書いたコードが最高の教材)</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>エンジンのレイヤ構造を紙に描き、依存方向のルールを述べよ。</li><li>継承/コンポーネント/ECSの3モデルの得失を、キャッシュと柔軟性の 観点で比較せよ。</li><li>スパースセット型ECSのadd/get/イテレーションの計算量とメモリ配置は?</li><li>アーキタイプ型が「構成変更に弱い」のはなぜか。</li><li>クックとは何か。なぜ実行時にFBXを直接読まないのか。</li><li>物理とレンダリングの更新順序はどちらが先か。理由は?</li><li>自作エンジンで一番設計をやり直した箇所はどこか(自分の言葉で)。</li></ol><hr><h2 id="この章がゲームのどこで使われているか" tabindex="-1">この章がゲームのどこで使われているか <a class="header-anchor" href="#この章がゲームのどこで使われているか" aria-label="Permalink to &quot;この章がゲームのどこで使われているか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1フレーム = エンジンという工場のベルトコンベア</span></span>
<span class="line"><span>────────────────────────────────────────────────</span></span>
<span class="line"><span>[入力] → [ゲームシステム群の更新(ECS: 連続データを一括処理)]</span></span>
<span class="line"><span>       → [物理(グリッド/BVH→解決)] → [アニメ(ボーン行列)]</span></span>
<span class="line"><span>       → [カメラ] → [カリング] → [描画コマンド生成(ソート)]</span></span>
<span class="line"><span>       → [RHI提出(第13章)] → [Present]</span></span>
<span class="line"><span>  ↑ この工程表・部品配置・メモリ計画を設計するのがエンジン設計</span></span>
<span class="line"><span>  ↑ Unity/UEは この図の巨大産業版(次の2章で内部を見る)</span></span>
<span class="line"><span>アセット: FBX/PNG →(クック)→ 最適バイナリ →(非同期ロード)→ VRAM/ヒープ</span></span></code></pre></div>`,29)])])}const g=l(e,[["render",s]]);export{u as __pageData,g as default};
